fn replace_last_element(first: &Vec<i32>, second: &Vec<i32>) -> Vec<i32> {
    // Since first.len() > 0, safe to do first.len() - 1
    let mut replaced_list = Vec::with_capacity((first.len() - 1) + second.len());

    // Copy all elements from first except the last one
    for i in 0..(first.len() - 1) {
        replaced_list.push(first[i]);
    }

    // Append all elements from second
    for &item in second.iter() {
        replaced_list.push(item);
    }

    replaced_list
}